import{_ as s,l,o as e,c as n,v as r,p as i,x as t,d as c,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"事务内存","description":"","frontmatter":{"title":"事务内存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/transactional-memory.md","filePath":"cs/transactional-memory.md","lastUpdated":1789023840000}'),h={name:"cs/transactional-memory.md"};function p(m,a,A,B,_,u){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="事务内存" tabindex="-1">事务内存 <a class="header-anchor" href="#事务内存" aria-label="Permalink to &quot;事务内存&quot;">​</a></h1><div class="epigraph"><p>用 cache 的独占与共享跟踪读集写集：提交时若没有冲突则一次性对全局可见，否则丢掉推测写，像误预测一样恢复。</p><footer>—— 据 Herlihy and Moss, Transactional Memory: Architectural Support for Lock-Free Data Structures, ISCA 1993 整理</footer></div><p><a href="/cs/acquire-release">上一课</a> 用锁的两端串可见性，锁本身仍是真共享行上的争用。<a href="/cs/atomic-cache-impl">原子</a> 一次只罩一个地址。本课不重讲 dmb。缺口是<strong>硬件事务内存（HTM）：把临界区里的多行读写当成可提交或可放弃的一块</strong>，用 cache 状态当读集/写集。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>细粒度锁难写；粗粒度锁把伪共享变成真串行。无锁算法用 CAS 循环，可组合性差。Herlihy–Moss 的提案：指令标明事务开始/结束，硬件保证「看起来原子」。缺口不是更强的 fence，而是<strong>用已有的一致性探询检测冲突：他核对你读集的写、或对你写集的任何访问，导致 abort。</strong></p><p><span class="marginnote">Intel TSX（RTM/HLE）把 L1 当写缓冲：容量溢出、异常、某些指令都会 abort，软件必须有回退路径。这是有限 HTM，不是无限理想事务。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事务中：load 把行留在 S/E 并加入读集；store 把行升到 M 但<strong>不对外提交</strong>（可把数据放在 L1 私有副本）。探询打中读集或写集则 abort：冲刷写集，像 <a href="/cs/speculation-recovery">推测恢复</a>。提交：写集一次性变成全局 M 可见，或靠「提交前检查读集仍有效」。</p>',8)),(e(),i(E,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEGIN%5B%22%E4%BA%8B%E5%8A%A1%E5%BC%80%E5%A7%8B%22%5D%20--%3E%20RS%5B%22%E8%AF%BB%E9%9B%86%20S%22%5D%0A%20%20BEGIN%20--%3E%20WS%5B%22%E5%86%99%E9%9B%86%E7%A7%81%E6%9C%89%20M%22%5D%0A%20%20PROBE%5B%22%E4%BB%96%E6%A0%B8%E6%8E%A2%E8%AF%A2%E5%86%B2%E7%AA%81%22%5D%20--%3E%20ABORT%5B%22%E4%B8%A2%E5%86%99%E9%9B%86%EF%BC%8C%E5%9B%9E%E9%80%80%22%5D%0A%20%20END%5B%22%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20PUB%5B%22%E5%86%99%E9%9B%86%E4%B8%80%E6%AC%A1%E6%80%A7%E5%8F%AF%E8%A7%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 ROB 推测的差别：事务跨越的是<strong>内存行</strong>，可以比 ROB 窗口长，但受 L1 容量限制。与锁：无冲突时无锁字颠簸；有冲突时 abort 重试可能活锁，需要指数退避或回退到锁。不能把 HTM 当成可以省略 <a href="/cs/acquire-release">acquire/release</a> 的魔法——失败路径仍是锁。</p><p>禁止在事务里做的事（I/O、某些特权、过深嵌套）来自「写集无法回滚外部世界」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 STM（纯软件）当微结构主干。也不提供可运行的锁省略攻击或侧信道利用；事务 abort 会改 cache，安全课可再引用。下一课把显式 fence 的周期数钉下来：没有事务、没有锁时，程序员仍会下栅栏。</p><p>后课默认：HTM 用 cache 做多行推测原子，容量与指令集有限。显式 fence 仍是最可控的顺序工具，但很贵。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HTM 用读集/写集与探询做冲突检测，提交或 abort。</li><li>容量与禁止指令强制软件回退。</li><li>显式 fence 的微结构代价是下一课。</li><li>出处：Herlihy and Moss, <em>ISCA</em>, 1993；Intel TSX 公开文档。</li></ul>',8))])}const S=s(h,[["render",p]]);export{T as __pageData,S as default};
